begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,aud,role,email) values
 ('a7272727-2727-4272-8272-272727272727','authenticated','authenticated','rejoin-a@example.invalid'),
 ('b7272727-2727-4272-8272-272727272727','authenticated','authenticated','rejoin-b@example.invalid'),
 ('c7272727-2727-4272-8272-272727272727','authenticated','authenticated','rejoin-c@example.invalid');
create temporary table rejoin_state(j jsonb,old_grant jsonb,old_generation bigint);
grant all on rejoin_state to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','a7272727-2727-4272-8272-272727272727',true);
insert into rejoin_state(j) select public.phase8_group_command('create');
select is((select j->>'phase' from rejoin_state),'lobby','create remains lobby');
select is(public.phase8_group_command('start',(select (j->>'id')::uuid from rejoin_state))->>'phase','running','admin starts');
select set_config('request.jwt.claim.sub','b7272727-2727-4272-8272-272727272727',true);
select is(public.phase8_group_command('join',null,(select j->>'inviteCode' from rejoin_state))->>'phase','running','new user joins running');
update rejoin_state set old_grant=public.phase8_group_command('share_start',(j->>'id')::uuid,null,null,true)->'grant';
update rejoin_state set old_generation=(public.phase8_group_command('current')->>'generation')::bigint;
select lives_ok($q$select public.phase8_group_command('leave',(select (j->>'id')::uuid from rejoin_state))$q$,'member leaves');
select lives_ok($q$select public.phase8_group_command('join',null,(select j->>'inviteCode' from rejoin_state))$q$,'LEFT rejoins same invite');
select is(public.phase8_group_command('current')->>'phase','running','rejoin preserves running');
select is(jsonb_array_length(public.phase8_group_command('current')->'members'),2,'active membership counted once');
select is(jsonb_array_length(public.phase8_group_command('join',null,(select j->>'inviteCode' from rejoin_state))->'members'),2,'join retry is idempotent');
select ok((public.phase8_group_command('current')->>'generation')::bigint>(select old_generation from rejoin_state),'old channel generation revoked');
select is((select m->>'sharingStatus' from jsonb_array_elements(public.phase8_group_command('current')->'members') m where m->>'accountId'='b7272727-2727-4272-8272-272727272727'),'off','rejoin never restores sharing');
select isnt((select m->>'membershipId' from jsonb_array_elements(public.phase8_group_command('current')->'members') m where m->>'accountId'='b7272727-2727-4272-8272-272727272727'),(select old_grant->>'membershipId' from rejoin_state),'rejoin has fresh membership identity');
reset role;
select throws_ok($q$select public.phase8_group_accept_location('b7272727-2727-4272-8272-272727272727',(select (j->>'id')::uuid from rejoin_state),(select (old_grant->>'membershipId')::uuid from rejoin_state),(select (old_grant->>'publicationId')::uuid from rejoin_state),(select (public.phase8_group_command('current')->>'generation')::bigint),10,20,5,1,clock_timestamp())$q$,'42501',null,'old publication cannot revive');
set local role authenticated;
select set_config('request.jwt.claim.sub','a7272727-2727-4272-8272-272727272727',true);
select lives_ok($q$select public.phase8_group_command('leave',(select (j->>'id')::uuid from rejoin_state))$q$,'administrator leaves');
select lives_ok($q$select public.phase8_group_command('join',null,(select j->>'inviteCode' from rejoin_state))$q$,'former administrator rejoins');
select is((select m->>'role' from jsonb_array_elements(public.phase8_group_command('current')->'members') m where m->>'accountId'='a7272727-2727-4272-8272-272727272727'),'member','administrator role is not restored');
select throws_ok($q$select public.phase8_group_command('end',(select (j->>'id')::uuid from rejoin_state))$q$,'42501','administrator_required','former administrator lacks admin powers');
select set_config('request.jwt.claim.sub','c7272727-2727-4272-8272-272727272727',true);
select lives_ok($q$select public.phase8_group_command('join',null,(select j->>'inviteCode' from rejoin_state))$q$,'third user late joins');
select set_config('request.jwt.claim.sub','b7272727-2727-4272-8272-272727272727',true);
select lives_ok($q$select public.phase8_group_command('ban',(select (j->>'id')::uuid from rejoin_state),null,(select (m->>'membershipId')::uuid from jsonb_array_elements(public.phase8_group_command('current')->'members') m where (m->>'joinOrder')::int=4))$q$,'new administrator bans third user');
select set_config('request.jwt.claim.sub','c7272727-2727-4272-8272-272727272727',true);
select throws_ok($q$select public.phase8_group_command('join',null,(select j->>'inviteCode' from rejoin_state))$q$,'42501','membership_banned','banned user cannot rejoin');
select set_config('request.jwt.claim.sub','b7272727-2727-4272-8272-272727272727',true);
select lives_ok($q$select public.phase8_group_command('end',(select (j->>'id')::uuid from rejoin_state))$q$,'new administrator ends');
select set_config('request.jwt.claim.sub','a7272727-2727-4272-8272-272727272727',true);
select throws_ok($q$select public.phase8_group_command('join',null,(select j->>'inviteCode' from rejoin_state))$q$,'P0002','invite_unavailable','ended group cannot be rejoined');
update rejoin_state set j=public.phase8_group_command('create');
reset role;
update public.phase8_groups set expires_at=clock_timestamp()-interval '1 second' where id=(select (j->>'id')::uuid from rejoin_state);
set local role authenticated;
select throws_ok($q$select public.phase8_group_command('join',null,(select j->>'inviteCode' from rejoin_state))$q$,'P0002','invite_unavailable','expired group cannot be rejoined');
reset role;
select * from finish();
rollback;
